# demo: find largest solid rectangle of a non-zero color

def rects(g):
    H=len(g);W=len(g[0]);res=[]
    for c in set(x for r in g for x in r):
        if c==0: continue
        for top in range(H):
            for left in range(W):
                if g[top][left]!=c: continue
                w=h=1
                while top+h<H and g[top+h][left]==c: h+=1
                while left+w<W and g[top][left+w]==c: w+=1
                res.append((h*w,c,top,left,h,w))
    return sorted(res,reverse=True)

