# maximal solid rectangles of single nonzero color (maximal means cannot extend in any direction)
def max_rects(g):
    H,W=g.shape
    out=[]
    for col in set(map(int,g.flatten()))-{0}:
        m=g==col
        # use connected components of True mask
        seen=np.zeros_like(m); 
        for i in range(H):
            for j in range(W):
                if m[i,j] and not seen[i,j]:
                    from collections import deque
                    q=deque([(i,j)]); seen[i,j]=True; ys=[i]; xs=[j]
                    while q:
                        y,x=q.popleft()
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=True; q.append((ny,nx)); ys.append(ny); xs.append(nx)
                    r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                    fill=len(ys)/(r1-r0+1)*(c1-c0+1)
                    if r1-r0+1>=2 and c1-c0+1>=2 and fill>0.95:
                        sub=g[r0:r1+1,c0:c1+1]
                        out.append((r0,r1,c0,c1,int(col),sub.tolist()))
    return out
