import numpy as np, json
def solve(g):
    A=np.array(g); H,W=A.shape
    seen=np.zeros_like(A,dtype=bool); comps=[]
    for i in range(H):
        for j in range(W):
            if A[i,j]!=0 and not seen[i,j]:
                c=int(A[i,j]); q=[(i,j)]; seen[i,j]=True; ys=[i]; xs=[j]
                while q:
                    y,x=q.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and int(A[ny,nx])==c and not seen[ny,nx]:
                            seen[ny,nx]=True; q.append((ny,nx)); ys.append(ny); xs.append(nx)
                ys=sorted(set(ys)); xs=sorted(set(xs))
                h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
                fill=len(q)/(h*w)
                comps.append((h,w,int(c),fill,len(q)))
    comps.sort(key=lambda x:(x[0]*x[1],x[3]),reverse=True)
    h,w,col,fill,_=comps[0]
    return [[col]*w for _ in range(h)]
